const merzlyak5Extra: GdzProblem[  ] = [ { number: '32', page: 20, condition: 'Трёхзначное число записали подряд два раза. Во сколько раз полученное шестизначное число больше данного трёхзначного', steps: ['Смотрим на десятки: 4 < 5, округляем вниз.', '7 846 ≈ 7 800.'], answer: '7 800.' },
  { number: '38', page: 24, condition: 'Первый полёт в космос совершил в 1961 г. гражданин Советского Союза Юрий Гагарин. Через восемь', steps: ['30 = 2·3·5, 45 = 3²·5.', 'НОД = 3·5 = 15.'], answer: '15.' },
  { number: '42', page: 26, condition: 'За три дня кузнец Вакула изготовил 432 подковы. Сколько подков он изготовит за пять дней, работая с такой же', steps: ['248 · 35 = 248 · 30 + 248 · 5 = 7440 + 1240 = 8680.'], answer: '8680.' },
  { number: '48', page: 28, condition: 'Запишите все отрезки, изображённые на рисунке 16. Начертите отрезки EF и ВК так, чтобы EF = 9 см 2 мм, ВК = 5 см 4 мм. Сравните эти отрезки.', steps: ['EF = 9 см 2 мм = 92 мм.', 'ВК = 5 см 4 мм = 54 мм.', 'EF > ВК, так как 92 мм > 54 мм.'], answer: 'EF > ВК.' },
  { number: '58', page: 30, condition: 'Начертите в тетради ломаную, изображённую на рисунке 20. Измерьте длины звеньев (в миллиметрах) и найдите длину', steps: ['Сумма цифр: 2+3+4 = 9. Делится на 9.', 'Да, 234 кратно 9.'], answer: 'Да.' },
  { number: '62', page: 32, condition: 'Известно, что MF = 43 см, ME = 26 см, КЕ = 18 см (рис. 24). Найдите длины отрезков МК и', steps: ['Сумма цифр: 7+4+1 = 12. 12 делится на 3.', 'Да, 741 кратно 3.'], answer: 'Да.' },
  { number: '68', page: 34, condition: 'Постройте ломаную АСDМ так, чтобы АС = 15 мм, CD = 24 мм, DM = 32 мм. Вычислите длину', steps: ['60 = 2·30 = 2·2·15 = 2·2·3·5 = 2²·3·5.'], answer: '60 = 2²·3·5.' },
  { number: '75', page: 36, condition: 'Известно, что АЕ = 12 см, AQ = QB, BM = MC, СК = KD, DR = RE, MK = 4 см (рис. 30). Найдите длину отрезка', steps: ['6 = 2·3, 15 = 3·5.', 'НОК = 2·3·5 = 30.'], answer: '30.' },
  { number: '140', page: 62, condition: 'Стоимость 7 кг яблок такая же, как 4 кг груш. Сколько килограммов груш можно купить на ту же сумму, что и 42 кг', steps: ['3½ = (3·2+1)/2 = 7/2.'], answer: '7/2.' },
  { number: '145', page: 64, condition: 'Сравните числа: 1) 642 и 624; 5) 1 400 140 и 1 401 400; 2) 786 и 779; 6) 224 978 и 224 988; 3) 4 897 и 5 010; 7) 6 130 852 и 6', steps: ['НОК=10. 2/5=4/10.', '4/10+3/10=7/10.'], answer: '7/10.' },
  { number: '150', page: 66, condition: 'Отметьте на координатном луче все натуральные числа, которые: 1) меньше 12; 2) больше 4, но меньше', steps: ['1/4 · x = 3/4. x = 3/4 · 4 = 3 м.'], answer: '3 м.' },
  { number: '255', page: 120, condition: 'Упростите выражение и найдите его значение: 1) 476+а+224, если а=221; 2) х+246-46, если х=137; 3) 973-243-у, если', steps: ['3 : 4 = 0,75.'], answer: '0,75.' },
  { number: '260', page: 122, condition: 'Мальвина купила 8 конфет по а сольдо и b пирожных по 65 сольдо, заплатив за конфеты меньше, чем', steps: ['2,35 + 1,80 = 4,15.'], answer: '4,15.' },
  { number: '265', page: 124, condition: 'Масса полного ящика с яблоками составляет 25 кг. После того как продали половину яблок, масса', steps: ['5,00 − 2,37 = 2,63.'], answer: '2,63.' },
  { number: '270', page: 126, condition: 'Решите уравнение: 1) x+48=94; 3) x-174=206; 2) 234+y=452; 4)', steps: ['45 · 22 = 990. Знаков после запятой: 1+1=2.', '4,5 · 2,2 = 9,90 = 9,9.'], answer: '9,9.' },
  { number: '275', page: 128, condition: 'Какое число надо подставить вместо a, чтобы корнем уравнения: 1) (х+а)-7=42 было число 22; 2) (а-х)+4=15 было число', steps: ['7,2 : 0,8 = 72 : 8 = 9.'], answer: '9.' },
  { number: '465', page: 222, condition: 'Сколько килограммов масла можно изготовить из 261 кг сливок, если из 9 кг сливок получается 2', steps: ['0,4 · 250 = 100.'], answer: '100.' },
  { number: '470', page: 224, condition: 'Из городов Цветочный и Солнечный, расстояние между которыми равно 136 км, выехали', steps: ['Скидка = 3000 · 0,2 = 600. Цена = 3000 − 600 = 2400 руб.'], answer: '2400 руб.' } ]
